// Embedded brand-asset fallback. Used only if GitHub Pages cannot resolve /assets files.
window.KD_ASSETS = {
  hero: "data:image/png;base64,",
  avatar: "data:image/png;base64,"
};
function kdAssetFallback(img, key){
  if(!img || !window.KD_ASSETS || !window.KD_ASSETS[key]) return;
  if(img.dataset.kdFallbackApplied) return;
  img.dataset.kdFallbackApplied = '1';
  img.src = window.KD_ASSETS[key];
}
